// DEMO-3 — the public MCP surface for kill_agent.
use crate::kill_agent::{kill_agent, KillOutcome, SessionId};

#[derive(Debug, PartialEq, Eq)]
pub enum McpError {
    AlreadyExited,
    NotFound,
    PermissionDenied,
}

pub fn mcp_kill_agent(
    caller_principal: &str,
    session_id: &str,
    grace_ms: Option<u32>,
) -> Result<KillOutcome, McpError> {
    let session = lookup_session(session_id).ok_or(McpError::NotFound)?;
    if session.owner_principal != caller_principal {
        return Err(McpError::PermissionDenied);
    }
    let outcome = kill_agent(&SessionId(session_id.to_string()), grace_ms.unwrap_or_else(|| session.graceful_shutdown_ms));
    Ok(outcome)
}

struct Session { owner_principal: String, graceful_shutdown_ms: u32 }
fn lookup_session(_: &str) -> Option<Session> { Some(Session { owner_principal: "example".into(), graceful_shutdown_ms: 3_000 }) }

